{
  "title": "URL Shortener Service",
  "summary": "A service that creates short links for http/https URLs, with an optional custom alias and expiry, and redirects short codes to their long URLs. It records per-link click statistics (clicks per day, top referrers) and must sustain 1,000 redirects/second on one node, continuing to redirect when the cache is unavailable.",
  "goals": [
    "Create a short link from a valid long URL, with an optional custom alias and optional expiry time",
    "Redirect a short code to its long URL quickly and reliably",
    "Expose per-link click statistics: clicks per day and top referrers",
    "Keep redirecting when the cache is down by falling back to the primary data store",
    "Reject unsafe or invalid destination URLs at creation time"
  ],
  "nonFunctional": [
    "Throughput: sustain 1,000 redirects/second on a single node for at least 5 minutes with an error rate below 0.1%",
    "Latency with a healthy cache: p95 redirect latency <= 50 ms and p99 <= 150 ms at 1,000 redirects/second",
    "Latency with the cache down: p95 redirect latency <= 150 ms at 1,000 redirects/second, with 0 redirect failures caused by the cache outage",
    "Recording a click must never block or fail a redirect: if the statistics write fails, the redirect still succeeds",
    "Statistics freshness: a click appears in the statistics within 60 seconds under normal operation",
    "Link creation: p95 latency <= 500 ms, including URL safety checks",
    "Generated short codes are unique; concurrent creation requests for the same alias result in exactly one success"
  ],
  "acceptanceCriteria": [
    {
      "id": "AC1",
      "given": "a valid long URL with an http or https scheme and a public host",
      "when": "a client creates a short link without an alias or expiry",
      "then": "the service returns a unique generated short code and short URL, and the link does not expire"
    },
    {
      "id": "AC2",
      "given": "a valid long URL and an unused, well-formed custom alias",
      "when": "a client creates a short link with that alias",
      "then": "the short code equals the alias and requesting it redirects to the long URL"
    },
    {
      "id": "AC3",
      "given": "a custom alias that is already in use",
      "when": "a client creates a short link with that alias",
      "then": "the service responds with a conflict error (HTTP 409), and the existing link is unchanged"
    },
    {
      "id": "AC4",
      "given": "a custom alias that is malformed or reserved",
      "when": "a client creates a short link with that alias",
      "then": "the service rejects the request with a validation error (HTTP 400) naming the alias as the problem"
    },
    {
      "id": "AC5",
      "given": "an existing, unexpired short link",
      "when": "a client requests the short code",
      "then": "the service responds with a redirect (HTTP 302) whose Location header is the exact long URL"
    },
    {
      "id": "AC6",
      "given": "a short code that does not exist",
      "when": "a client requests it",
      "then": "the service responds with HTTP 404 and no redirect"
    },
    {
      "id": "AC7",
      "given": "a short link created with an expiry time in the future",
      "when": "the expiry time has passed and a client requests the short code",
      "then": "the service responds with HTTP 410 Gone and no redirect, even if the link was previously cached"
    },
    {
      "id": "AC8",
      "given": "an expiry time that is in the past or not a valid ISO-8601 UTC timestamp",
      "when": "a client creates a short link",
      "then": "the service rejects the request with a validation error (HTTP 400) and creates no link"
    },
    {
      "id": "AC9",
      "given": "a long URL whose scheme is not http or https (for example ftp:, javascript:, data:, file:)",
      "when": "a client creates a short link",
      "then": "the service rejects the request with a validation error (HTTP 400) and creates no link"
    },
    {
      "id": "AC10",
      "given": "a long URL whose host is a loopback, private, link-local, or otherwise non-public address (literal IP such as 127.0.0.1, 10.0.0.5, 192.168.1.1, 169.254.169.254, [::1], or a hostname that resolves to one)",
      "when": "a client creates a short link",
      "then": "the service rejects the request with a validation error (HTTP 400) and creates no link"
    },
    {
      "id": "AC11",
      "given": "an existing short link that has received redirects on several UTC days",
      "when": "a client requests the statistics for that link",
      "then": "the response lists the click count for each UTC day with at least one click, and the counts sum to the total number of successful redirects recorded"
    },
    {
      "id": "AC12",
      "given": "an existing short link that has received redirects with various Referer headers, including some with none",
      "when": "a client requests the statistics for that link",
      "then": "the response lists the top referrer hosts in descending order of clicks, with a limit of 10, and clicks with no referrer are grouped under 'direct'"
    },
    {
      "id": "AC13",
      "given": "the cache is unavailable (connection refused or timing out)",
      "when": "a client requests an existing, unexpired short code",
      "then": "the service still responds with the correct redirect, served from the primary data store"
    },
    {
      "id": "AC14",
      "given": "the statistics store is temporarily failing writes",
      "when": "a client requests an existing short code",
      "then": "the redirect still succeeds"
    },
    {
      "id": "AC15",
      "given": "a single node under a load of 1,000 redirects/second for 5 minutes, first with a healthy cache and then with the cache down",
      "when": "the load test completes",
      "then": "the error rate is below 0.1% and the latency targets for each case are met"
    }
  ],
  "ambiguities": [
    {
      "question": "Who may create links and who may view a link's statistics? The requirement does not mention authentication or ownership, and referrer data can be sensitive.",
      "proposedDefault": "Link creation and redirects are open, with basic per-client rate limiting on creation. Each link gets an unguessable management token at creation, and statistics require that token. Full user accounts are out of scope.",
      "confidence": "LOW"
    },
    {
      "question": "What click data may be stored and for how long? Per-day counts and referrers do not require IP addresses or user agents, but the requirement does not set retention.",
      "proposedDefault": "Store only the click timestamp (aggregated by UTC day) and the referrer host, with no IP, user agent, or full referrer URL. Keep aggregates for the life of the link, with no raw-event retention beyond 30 days.",
      "confidence": "LOW"
    },
    {
      "question": "How should private/loopback address blocking handle hostnames that resolve to private IPs, and DNS rebinding (a host that resolves to a public IP at creation and a private one later)?",
      "proposedDefault": "At creation, reject literal non-public IPs (including IPv6 and IPv4-mapped forms, decimal/hex/octal encodings) and resolve the hostname, rejecting if any resolved address is non-public. Do not re-resolve at redirect time, because the service only issues redirects and never fetches the URL. Document this residual risk.",
      "confidence": "LOW"
    },
    {
      "question": "Which redirect status code should be used? 301 is cached by browsers, which undercounts clicks and makes destinations hard to change, while 302 is not cached.",
      "proposedDefault": "HTTP 302, so every click reaches the service and is counted.",
      "confidence": "MEDIUM"
    },
    {
      "question": "What are the custom alias rules (characters, length, case sensitivity, reserved words)?",
      "proposedDefault": "3-32 characters from [A-Za-z0-9_-], case-sensitive. Reserved words such as 'api', 'admin', 'stats', and 'health' are rejected. Generated codes are 7-character base62 and never collide with existing aliases.",
      "confidence": "MEDIUM"
    },
    {
      "question": "What is the expiry format and what response is given for expired links?",
      "proposedDefault": "Expiry is an absolute ISO-8601 UTC timestamp, at least 1 minute in the future and at most 5 years out. Expired links return HTTP 410. Expired links and their statistics are retained, not deleted.",
      "confidence": "MEDIUM"
    },
    {
      "question": "Should the same long URL submitted twice return the same short code?",
      "proposedDefault": "No. Each create request produces a new short link, so each link has independent statistics and expiry.",
      "confidence": "MEDIUM"
    },
    {
      "question": "Does the 1,000 redirects/second target also apply while the cache is down, and how fresh must statistics be?",
      "proposedDefault": "Yes, the throughput target applies in both modes, with a relaxed p95 latency of 150 ms without the cache. Click counting is asynchronous, best-effort, and eventually consistent within 60 seconds. A small loss during a statistics store outage is acceptable, but the redirect must not fail.",
      "confidence": "MEDIUM"
    },
    {
      "question": "What defines a 'day' in clicks per day, and how many days are returned?",
      "proposedDefault": "UTC calendar days. The response covers the last 30 days by default, with optional from/to query parameters and zero-click days omitted or returned as 0 consistently.",
      "confidence": "HIGH"
    },
    {
      "question": "How are referrers identified and how many are shown in 'top referrers'?",
      "proposedDefault": "Group by the host of the Referer header, lowercased. Missing or unparseable referrers are counted as 'direct'. Return the top 10.",
      "confidence": "MEDIUM"
    },
    {
      "question": "What is the maximum accepted long URL length?",
      "proposedDefault": "2,048 characters. Longer URLs are rejected with HTTP 400. Credentials embedded in the URL (user:pass@host) are rejected.",
      "confidence": "MEDIUM"
    }
  ],
  "assumptions": [
    "The service exposes an HTTP API: a create endpoint, a redirect endpoint at /{code}, and a statistics endpoint per link",
    "A durable primary data store is the source of truth, and the cache is an optional read-through acceleration layer that holds no data not in the store",
    "The cache TTL for a link never exceeds its remaining time to expiry",
    "A single node is the unit of the throughput target. Horizontal scaling is not required, but nothing should prevent it",
    "Short codes are case-sensitive and the base URL for short links is configurable",
    "Only successful redirects (HTTP 302) count as clicks. 404 and 410 responses do not",
    "Bot and duplicate click filtering is not applied. All redirects count"
  ],
  "outOfScope": [
    "User accounts, login, and team or organisation management",
    "Editing or deleting links after creation",
    "Link preview pages, QR code generation, and custom domains",
    "Per-click geolocation, device, or browser analytics",
    "Bot detection and click de-duplication",
    "Scanning destinations for malware or phishing reputation",
    "Multi-node or multi-region deployment and cache high availability",
    "A web UI. This is an API-only service"
  ]
}
